def error_rate(lines, service):
    entries = []
    for line in lines:
        if not line.strip():
            continue
        entries.append(parse_line(line))
    service_entries = [e for e in entries if e["service"] == service]
    if not service_entries:
        return 0.0
    errors = [e for e in service_entries if e["level"] == "ERROR"]
    return len(errors) / len(service_entries)
